import { expect, expectStatus, test } from "../../fixtures";

test.describe("vendor list search and status filter", () => {
  test("search and the status filter apply together", { tag: "@LIF-14" }, async ({ apiAs, factory }) => {
    // Arrange: one unique word shared by a draft vendor and a vendor in review
    const member = await apiAs("member");
    const word = `lif14${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
    const draft = await factory.vendor({ name: `${word} draft` });
    const { vendor: inReview } = await factory.vendorInReview({ name: `${word} review` });

    // Act
    const response = await member.get("/api/vendors", {
      params: { q: word, status: "in_review" },
    });

    // Assert
    const page = await expectStatus<{ items: { id: string; name: string; status: string }[]; total: number }>(
      response,
      200,
    );
    expect(page.items.map((v) => v.id)).toEqual([inReview.id]);
    expect(page.items.map((v) => v.id)).not.toContain(draft.id);
    expect(page.items[0].status).toBe("in_review");
    expect(page.total).toBe(1);
  });
});
